WITH item_sales AS (SELECT i.i_item_sk, i.i_product_name, hd.hd_income_band_sk, hd.hd_vehicle_count, i.i_current_price, SUM(ws.ws_quantity) AS total_quantity_sold, SUM(ws.ws_net_profit) AS total_net_profit, SUM(ws.ws_ext_discount_amt) AS total_discount_amt, SUM(ws.ws_ext_list_price) AS total_list_price FROM web_sales ws INNER JOIN item i ON ws.ws_item_sk = i.i_item_sk INNER JOIN promotion p ON ws.ws_promo_sk = p.p_promo_sk AND p.p_item_sk = i.i_item_sk INNER JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk WHERE p.p_discount_active = 'Y' GROUP BY i.i_item_sk, i.i_product_name, hd.hd_income_band_sk, hd.hd_vehicle_count, i.i_current_price) SELECT i_item_sk, i_product_name, hd_income_band_sk, hd_vehicle_count, total_quantity_sold, total_net_profit, ROUND(100.0 * total_discount_amt / NULLIF(total_list_price, 0), 2) AS avg_discount_percent, CASE WHEN i_current_price < 10 THEN 'Cheap' WHEN i_current_price BETWEEN 10 AND 50 THEN 'Medium' ELSE 'Expensive' END AS price_category, RANK() OVER (ORDER BY total_net_profit DESC) AS profit_rank FROM item_sales ORDER BY total_net_profit DESC
